import { t, ui, locale, onLanguageChange } from './i18n.js';
const html=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const date=value=>{const d=new Date(value);return value&&Number.isFinite(d.getTime())?new Intl.DateTimeFormat(locale(),{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(d):t('Non ancora');};
const bytes=value=>{const n=Number(value);return Number.isFinite(n)&&n>=0?n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`:t('Dimensione non disponibile');};
const setupLabels={runtime:'Runtime supportato',mode:'Modalità di installazione',https:'Indirizzo e HTTPS',identity:'Accesso del proprietario',encryption:'Archivio cifrato',workers:'Computer per i repository',backup:'Backup verificato',integrity:'Verifica dell’archivio'};
const statuses={ready:{label:'Pronto',icon:'✓'},action:{label:'Da configurare',icon:'→'},unknown:{label:'Da verificare',icon:'?'}};
const help=(label,text)=>ui`<details class="setup-help"><summary aria-label="Aiuto: ${html(label)}">?</summary><div><strong>${html(label)}</strong><p>${html(text)}</p></div></details>`;
const recordCount=value=>{const n=typeof value==='number'?value:typeof value?.total==='number'?value.total:null;return n===null?'':t('{count} record',{count:n});};

export function createSetupPanel({toast=()=>{}}={}){
  let host=null,snapshot=null,visible=false,loading=false,busy=false,downloading=null,error='',notice='',disposed=false,sequence=0;
  const controllers=new Set();
  async function request(path,body,{download=false}={}){
    const controller=new AbortController();controllers.add(controller);
    try{
      const response=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json','X-Fuori-Studio':'local'},body:JSON.stringify(body),signal:controller.signal}:{cache:'no-store',signal:controller.signal});
      if(!response.ok){let data;try{data=await response.json();}catch{}throw Error(response.status===404&&path==='/api/setup'?t('La preparazione guidata non è disponibile in questa versione del server. Riavvia lo studio con la versione aggiornata.'):data?.error||t('Lo studio non ha completato la richiesta. Riprova.'));}
      if(download)return response.blob();
      let data;try{data=await response.json();}catch{throw Error(t('Lo stato di preparazione non è disponibile. Riprova.'));}
      if(!data||!Array.isArray(data.checks)||!data.maintenance)throw Error(t('Lo stato di preparazione ricevuto non è valido.'));return data;
    }finally{controllers.delete(controller);}
  }
  function backupCard(item){
    return ui`<article class="setup-backup"><div class="setup-backup-main"><strong>${html(item.filename||t('Backup cifrato'))}</strong><p>${html(date(item.createdAt))} · ${html(bytes(item.bytes))}${recordCount(item.records)?` · ${html(recordCount(item.records))}`:''}</p><span class="setup-verification${item.verifiedAt?' is-verified':''}">${item.verifiedAt?html(t('Verificato {date}',{date:date(item.verifiedAt)})):t('Verifica non registrata')}</span>${item.sha256?ui`<details class="setup-checksum"><summary>Impronta SHA-256</summary><code>${html(item.sha256)}</code></details>`:''}</div><button type="button" class="access-button" data-setup-action="download" data-id="${html(item.id)}" aria-label="Scarica ${html(item.filename||t('backup cifrato'))}"${busy||loading?' disabled':''}>${downloading===item.id?t('Download…'):t('Scarica')}</button></article>`;
  }
  function render(){
    if(!host||!visible)return;
    const disabled=loading||busy,checks=snapshot?.checks||[],backups=[...(snapshot?.maintenance?.backups||[])].sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||'')),verification=snapshot?.maintenance?.lastVerification;
    const ready=checks.filter(item=>item.status==='ready').length,local=snapshot?.mode==='local',publicUrl=snapshot?.publicUrl;
    host.setAttribute('aria-busy',String(disabled));
    host.innerHTML=ui`<div class="setup-panel"><div class="access-intro"><div><span class="access-kicker">PREPARAZIONE DELLO STUDIO</span><h3>Ogni passaggio ha il suo stato.</h3><p>Controlla la configurazione, i computer disponibili e le copie dell’archivio.</p></div>${help(t('Configurato e verificato'),t('Questi stati provengono dal server. Una configurazione presente non dimostra da sola che il servizio esterno funzioni. Leggi il dettaglio di ogni controllo: se manca una prova, resta da verificare.'))}</div><div class="setup-toolbar"><span class="setup-progress">${snapshot?t('{ready} {label} su {total}',{ready,label:ready===1?t('controllo pronto'):t('controlli pronti'),total:checks.length}):t('Stato da rilevare')}</span><button type="button" class="access-button" data-setup-action="refresh"${disabled?' disabled':''}>${loading?t('Verifica dello stato…'):t('Aggiorna stato')}</button></div>${error?ui`<p class="setup-feedback is-error" role="alert">${html(error)}</p>`:notice?ui`<p class="setup-feedback" role="status">${html(t(notice))}</p>`:''}${!snapshot?ui`<div class="access-empty"><strong>${loading?t('Rilevamento della configurazione…'):t('Lo stato non è disponibile.')}</strong><p>${loading?t('Leggiamo i controlli dello studio, senza avviare servizi o modificare impostazioni.'):t('Aggiorna lo stato per riprovare. Le altre schede dell’account restano disponibili.')}</p></div>`:ui`<div class="setup-checklist" aria-label="Controlli di preparazione">${checks.map(item=>{const status=Object.hasOwn(statuses,item.status)?item.status:'unknown',label=statuses[status];return ui`<article class="setup-check is-${status}"><span class="setup-check-mark" aria-hidden="true">${label.icon}</span><div><div class="setup-check-title"><h4>${html(setupLabels[item.id] ? t(setupLabels[item.id]) : item.label)}</h4><span class="setup-status is-${status}">${t(label.label)}</span></div><p>${html(item.detail||t('Il server non ha fornito un dettaglio per questo controllo.'))}</p></div></article>`;}).join('')||ui('<p class="access-note">Nessun controllo restituito dal server.</p>')}</div><section class="setup-location"><div class="access-section-title"><h4>${local?t('Questa installazione'):t('Indirizzo dello studio')}</h4><span class="access-mode">${html(({get local(){return t('Locale');},get hybrid(){return t('Ibrido');},get online(){return t('Online');}})[snapshot.mode]||snapshot.mode)}</span></div><code>${html(publicUrl||(local?t('Accesso locale su questo computer'):t('Indirizzo pubblico non configurato')))}</code><p>${local?t('Per usare lo studio da altri dispositivi, prepara un’installazione online con un accesso protetto.'):t('L’indirizzo configurato deve corrispondere all’host HTTPS e al ritorno del servizio di identità. La raggiungibilità dall’esterno va verificata separatamente.')}</p><div class="setup-worker-summary"><span>${Number(snapshot.workers?.online)||0} computer online</span><span>${Number(snapshot.workers?.repositoryReady)||0} pronti per i repository</span><button type="button" class="access-link" data-setup-action="devices">Gestisci dispositivi ↗</button></div></section><details class="access-disclosure setup-guide"><summary>Come preparare l’accesso online</summary><ol><li><strong>Indirizzo e HTTPS.</strong> Configura l’host e <code>FUORI_STUDIO_PUBLIC_URL</code> sul server. Il proxy deve instradare correttamente lo studio e il dominio deve avere un certificato valido.</li><li><strong>Identità del proprietario.</strong> Registra l’applicazione OIDC, il ritorno <code>/auth/callback</code> e l’identificativo esatto del proprietario. Controlla il primo accesso con quell’account; MFA e recupero dipendono dal servizio di identità.</li><li><strong>Chiave dell’archivio.</strong> Conserva la chiave separatamente dal database. Per l’installazione online si configura sul server una chiave esterna, protetta insieme agli altri segreti dell’ambiente.</li><li><strong>Computer di lavoro.</strong> Da Dispositivi autorizza funzioni e ambiti. Collega il worker sul computer e registra dalla CLI i repository su cui può lavorare.</li></ol><p class="access-note">Le credenziali e i segreti si configurano sull’host. Questa scheda li rileva senza mostrarli o modificarli e non pubblica automaticamente lo studio.</p></details><section class="access-section setup-maintenance"><div class="access-section-title"><h4>Archivio e copie di sicurezza</h4>${help(t('Archivio, backup e chiave'),t('Verifica l’archivio controlla il database attuale e i suoi record cifrati. Crea backup salva e verifica una nuova copia cifrata. Per ripristinarla serve anche la chiave usata dall’installazione: conservala separatamente. Il ripristino si esegue dalla CLI, con il server fermo.'))}</div><div class="setup-storage"><span class="setup-storage-icon" aria-hidden="true">◇</span><div><strong>${snapshot.storage?.encrypted?t('Record cifrati a riposo'):t('Cifratura non confermata')}</strong><p>${snapshot.storage?.keySource==='environment'?t('Chiave gestita nell’ambiente del server'):snapshot.storage?.keySource==='local-file'?t('Chiave conservata in un file locale separato'):t('Origine della chiave non disponibile')}</p></div></div><p class="access-note">Il backup contiene l’archivio completo, comprese credenziali cifrate e cronologia. Per condividere solo alcune memorie, usa l’esportazione nella scheda Memoria.</p><div class="access-row-actions"><button type="button" class="access-button is-primary" data-setup-action="backup"${disabled?' disabled':''}>${busy&&!downloading?t('Operazione in corso…'):t('Crea backup cifrato')}</button><button type="button" class="access-button" data-setup-action="verify"${disabled?' disabled':''}>Verifica l’archivio</button></div><p class="setup-verification" role="status">${verification?html(t('Ultima verifica dell’archivio: {date}{records}.',{date:date(verification.verifiedAt),records:recordCount(verification.records)?` · ${recordCount(verification.records)}`:''})):t('L’archivio attuale non ha ancora una verifica registrata.')}</p><div class="setup-backups"><div class="access-section-title"><h4>Backup conservati</h4><span class="access-count">${backups.length}</span></div>${backups.length?backups.slice(0,8).map(backupCard).join(''):ui('<div class="access-empty"><strong>Non è ancora presente una copia.</strong><p>Crea un backup e scaricalo in un luogo sicuro. La chiave necessaria al ripristino va conservata separatamente.</p></div>')}${backups.length>8?ui`<p class="access-note">Mostrati gli 8 backup più recenti su ${backups.length}. Le altre copie restano sul server.</p>`:''}</div><p class="setup-key-note">Il file scaricato non contiene la chiave di decifratura. Il ripristino si effettua dalla CLI con il server fermo; una copia senza la sua chiave non è recuperabile.</p></section>`}</div>`;
  }
  async function load(){
    if(disposed||loading||busy)return;const version=++sequence;loading=true;error='';notice='';render();
    try{const value=await request('/api/setup');if(!disposed&&version===sequence)snapshot=value;}catch(e){if(!disposed&&version===sequence&&e.name!=='AbortError')error=e.message;}finally{if(version===sequence){loading=false;render();}}
  }
  async function mutate(action){
    if(disposed||loading||busy)return;busy=true;error='';notice='';render();
    try{const value=await request('/api/maintenance',{action});if(disposed)return;snapshot=value;notice=action==='backup'?'Backup creato. Controlla la verifica e scarica la copia.':'Verifica dell’archivio completata. Il risultato è riportato qui sotto.';toast(t(notice));}
    catch(e){if(!disposed&&e.name!=='AbortError')error=e.message;}finally{busy=false;render();}
  }
  async function download(id){
    if(disposed||loading||busy)return;const item=snapshot?.maintenance?.backups?.find(item=>item.id===id);if(!item)return;busy=true;downloading=id;error='';notice='';render();
    try{const blob=await request(`/api/maintenance/backup?id=${encodeURIComponent(id)}`,undefined,{download:true});if(disposed)return;const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=String(item.filename||'studio-backup.sqlite').split(/[\\/]/).at(-1);document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);notice='Download avviato. Conserva la chiave separatamente dalla copia cifrata.';}
    catch(e){if(!disposed&&e.name!=='AbortError')error=e.message;}finally{busy=false;downloading=null;render();}
  }
  function click(event){const button=event.target.closest('[data-setup-action]');if(!button||button.disabled)return;const action=button.dataset.setupAction;if(action==='refresh')void load();else if(action==='backup'||action==='verify')void mutate(action);else if(action==='download')void download(button.dataset.id);else if(action==='devices')window.dispatchEvent(new CustomEvent('studio-open-access',{detail:{section:'devices'}}));}
  function expire(){disposed=true;sequence++;snapshot=null;controllers.forEach(controller=>controller.abort());if(host)host.replaceChildren();}
  const unsubscribeLanguage=onLanguageChange(()=>{if(!disposed)render();});
  window.addEventListener('studio-session-expired',expire);
  return {attach(nextHost){if(host===nextHost){render();return;}host?.removeEventListener('click',click);host=nextHost;host?.addEventListener('click',click);render();},setVisible(value){const opening=!visible&&value;visible=Boolean(value);if(opening)void load();else if(visible)render();},refresh:load,getSnapshot:()=>snapshot,dispose(){unsubscribeLanguage();expire();host?.removeEventListener('click',click);window.removeEventListener('studio-session-expired',expire);host=null;}};
}
